function favoriteOptions(){const favorites=read('immobrain-listing-status-v1',{});$('plan-object').innerHTML='<option value="">Ohne Objektzuordnung</option>'+Object.entries(favorites).filter(([,v])=>v?.favorite).map(([key,v])=>{const x={...v.snapshot,...v.address};return `<option value="${esc(key)}">${esc([x.street,x.zipcode,x.city,x.title].filter(Boolean).join(' · '))}</option>`}).join('');if(plan.listingRef&&!Object.hasOwn(favorites,plan.listingRef))$('plan-object').innerHTML+=`<option value="${esc(plan.listingRef)}">Bisheriges Objekt (nicht mehr in Merkliste)</option>`;if(plan.listingRef&&favorites[plan.listingRef]&&!favorites[plan.listingRef].favorite)$('plan-object').innerHTML+=`<option value="${esc(plan.listingRef)}">Bisheriges Objekt (nicht mehr favorisiert)</option>`;$('plan-object').value=plan.listingRef||''}
