function renderSaved(){$('saved-plans').innerHTML=plans().map(p=>{const t=RenovationCore.totals(p);return `<article class="saved-plan${p.id===plan.id?' active':''}"><div><strong>${esc(p.name)}</strong><small>${t.done}/${t.tasks} Arbeitspakete erledigt · ${euro(t.total)}</small></div><button type="button" data-open-plan="${esc(p.id)}">Öffnen</button><button type="button" data-delete-plan="${esc(p.id)}">Löschen</button></article>`}).join('')||'<p class="empty-text">Noch keine Renovierungspläne gespeichert.</p>'}
