function save(){if(!$('plan-name').value.trim()){message('Bitte einen Plannamen oder eine Adresse eingeben.');$('plan-name').focus();return}if(!$('plan-reserve').reportValidity())return;const next={...clone(plan),id:plan.id||uid(),name:$('plan-name').value.trim(),updatedAt:new Date().toISOString()},all=plans(),index=all.findIndex(p=>p.id===next.id);if(index>=0)all[index]=next;else all.push(next);if(!write(KEY,all))return;plan=next;dirty=false;try{localStorage.removeItem(DRAFT)}catch{}const url=new URL(location.href);url.searchParams.set('plan',plan.id);url.searchParams.delete('checklist');history.replaceState(null,'',url.pathname+url.search+url.hash);renderSaved();message('Renovierungsplan gespeichert.')}
