$('plan-name').oninput=()=>{plan.name=$('plan-name').value;changed()};$('plan-reserve').oninput=()=>{plan.reserve=n($('plan-reserve').value);changed()};$('plan-object').onchange=()=>{plan.listingRef=$('plan-object').value;changed()};
$('new-plan').onclick=()=>{if(dirty&&!confirm('Ungespeicherte Änderungen verwerfen und einen neuen Plan starten?'))return;load(blank());try{localStorage.removeItem(DRAFT)}catch{}history.replaceState(null,'',location.pathname+'#uebersicht');activate()};
$('saved-plans').onclick=e=>{const button=e.target.closest('button');if(!button)return;const id=button.dataset.openPlan||button.dataset.deletePlan;if(button.dataset.openPlan){if(dirty&&!confirm('Ungespeicherte Änderungen verwerfen und den gespeicherten Plan öffnen?'))return;const next=plans().find(p=>p.id===id);if(next){load(next);history.replaceState(null,'','?plan='+encodeURIComponent(id)+location.hash)}}else if(button.dataset.deletePlan&&confirm('Diesen gespeicherten Renovierungsplan löschen?')){if(write(KEY,plans().filter(p=>p.id!==id))){if(plan.id===id){plan.id=null;changed();message('Gespeicherten Plan gelöscht. Die geöffneten Daten sind ein neuer Entwurf.')}renderSaved()}}};
$('preview-import').onclick=()=>{const source=checklists().find(v=>v.id===$('source-checklist').value);if(!source){$('import-message').textContent='Bitte zuerst eine gespeicherte Checkliste auswählen.';return}const rows=(source.data?.rows||[]).map((r,i)=>({...r,id:r.id||'legacy-'+i})).filter(r=>Number(r.action)>0);preview={...source,data:{...source.data,rows}};$('import-preview').innerHTML=rows.map((r,i)=>{const exists=plan.tasks.some(t=>t.sourceKey===source.id+':'+r.id);return `<label class="import-choice"><input type="checkbox" data-import-row="${i}" ${exists?'disabled':'checked'}><span><strong>${esc(r.label)} · ${esc(r.actions?.[r.action]||'Ausführen')}</strong><small>${n(r.qty)} ${esc(r.unit)} × ${euro(n(r.price))}${exists?' · Bereits übernommen':''}</small></span></label>`}).join('')||'<p>In dieser Checkliste sind noch keine Renovierungsmaßnahmen ausgewählt.</p>';$('import-checklist').hidden=!rows.some(r=>!plan.tasks.some(t=>t.sourceKey===source.id+':'+r.id));$('import-message').textContent='Nur markierte Maßnahmen werden übernommen; bestehende Arbeitspakete bleiben erhalten.'};
