$('import-checklist').onclick=()=>{if(!preview)return;const linked=preview.data?.fields?.listingRef;if(plan.listingRef&&linked&&plan.listingRef!==linked){$('import-message').textContent='Diese Checkliste gehört zu einem anderen Objekt. Bitte einen eigenen Renovierungsplan anlegen oder die Objektzuordnung vorher ändern.';return}const indices=[...$('import-preview').querySelectorAll('[data-import-row]:checked')].map(el=>Number(el.dataset.importRow));if(!indices.length){$('import-message').textContent='Bitte mindestens eine neue Maßnahme auswählen.';return}const result=RenovationCore.importChecklist(plan,{...preview,data:{...preview.data,rows:indices.map(i=>preview.data.rows[i])}},uid);plan=result.plan;$('plan-name').value=plan.name;$('plan-reserve').value=plan.reserve;favoriteOptions();render();changed();$('preview-import').onclick();$('import-message').textContent=result.added+' Arbeitspaket(e) mit Material- und Werkzeugvorschlägen übernommen.'};
$('trade-filter').onchange=renderTasks;$('task-filter').onchange=renderTasks;$('material-filter').onchange=()=>renderResources('material');$('tool-filter').onchange=()=>renderResources('werkzeug');
