$('add-task').onclick=()=>openTask();$('add-step').onclick=()=>{const label=$('new-step').value.trim();if(!label)return;steps.push({id:uid(),label,done:false});$('new-step').value='';renderSteps()};$('task-steps').onchange=e=>{const step=steps.find(s=>s.id===e.target.dataset.editStep);if(step)step.done=e.target.checked};$('task-steps').onclick=e=>{if(e.target.dataset.removeStep){steps=steps.filter(s=>s.id!==e.target.dataset.removeStep);renderSteps()}};
$('task-form').onsubmit=e=>{e.preventDefault();if(!$('task-form').reportValidity())return;const data=Object.fromEntries(new FormData($('task-form'))),old=plan.tasks.find(t=>t.id===data.id),t={...old,...data,id:data.id||uid(),title:data.title.trim(),trade:data.trade.trim()||'Allgemein',phase:Number(data.phase),qty:n(data.qty),unitPrice:n(data.unitPrice),steps:clone(steps)};if(!t.title)return;if(t.status==='erledigt')t.steps=t.steps.map(s=>({...s,done:true}));if(old)plan.tasks[plan.tasks.indexOf(old)]=t;else plan.tasks.push(t);$('task-dialog').close();changed();render()};
$('task-list').onchange=e=>{if(e.target.dataset.taskDone){const t=plan.tasks.find(t=>t.id===e.target.dataset.taskDone);if(t){t.status=e.target.checked?'erledigt':'offen';if(e.target.checked)t.steps=(t.steps||[]).map(s=>({...s,done:true}))}}else if(e.target.dataset.stepTask){const t=plan.tasks.find(t=>t.id===e.target.dataset.stepTask),step=t?.steps.find(s=>s.id===e.target.dataset.stepId);if(step){step.done=e.target.checked;if(t.steps.length&&t.steps.every(s=>s.done))t.status='erledigt';else if(t.status==='erledigt')t.status='in_arbeit'}}else return;changed();renderTasks()};
$('task-list').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.editTask)openTask(b.dataset.editTask);else if(b.dataset.deleteTask){if(!confirm('Arbeitspaket und ausschließlich dafür vorgesehene Beschaffungen entfernen? Gemeinsame Werkzeuge bleiben erhalten.'))return;const id=b.dataset.deleteTask;plan.tasks=plan.tasks.filter(t=>t.id!==id);plan.resources=plan.resources.filter(r=>!(r.taskIds?.length===1&&r.taskIds[0]===id)).map(r=>({...r,taskIds:(r.taskIds||[]).filter(key=>key!==id)}));changed();render()}else if(b.dataset.moveTask){const task=plan.tasks.find(t=>t.id===b.dataset.moveTask),group=filteredTasks().filter(t=>t.phase===task.phase),i=group.indexOf(task),other=group[i+Number(b.dataset.direction)];if(!other)return;const a=plan.tasks.indexOf(task),z=plan.tasks.indexOf(other);[plan.tasks[a],plan.tasks[z]]=[plan.tasks[z],plan.tasks[a]];changed();renderTasks()}};
